\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{tikz}
\usetikzlibrary{shapes.geometric, arrows.meta, positioning, shadows, backgrounds, calc}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{fontawesome5}
\pagestyle{empty}

% ── Security Dashboard Color Theme ──
\definecolor{primary}{HTML}{060E1A}       % Near-black navy (title bar)
\definecolor{secondary}{HTML}{0891B2}     % Teal (accent stripes, headers)
\definecolor{accent}{HTML}{0EA5E9}        % Electric blue (highlights)
\definecolor{metriccyan}{HTML}{22D3EE}    % Bright cyan (key metric numbers)
\definecolor{bgposter}{HTML}{0B1420}      % Deep navy background
\definecolor{bgcard}{HTML}{132339}        % Card background (navy)
\definecolor{bgtitle}{HTML}{0A1628}       % Card title bar background
\definecolor{bgstat}{HTML}{0D2946}        % Stat banner background
\definecolor{textlight}{HTML}{E2E8F0}     % Light text
\definecolor{textgray}{HTML}{94A3B8}      % Grey secondary text
\definecolor{textmuted}{HTML}{64748B}     % Muted text
\definecolor{stripecyan}{HTML}{06B6D4}    % Cyan stripe
\definecolor{stripeblue}{HTML}{0EA5E9}    % Blue stripe
\definecolor{stripegreen}{HTML}{10B981}   % Green stripe (uptime)
\definecolor{borderdim}{HTML}{1E3A5F}     % Subtle border

% ── Card tinted backgrounds ──
\definecolor{cyancardtint}{HTML}{0E243B}   % Cyan-tinted card
\definecolor{bluecardtint}{HTML}{0F2540}   % Blue-tinted card
\definecolor{navycardtint}{HTML}{101D33}   % Navy-tinted card

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=4pt, parsep=1pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=18pt, itemsep=4pt, parsep=1pt, topsep=2pt,
  label={\color{accent}\bfseries\arabic*.}}

% ── Figure + caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{20}{26}\selectfont\color{textgray}\textit{#3}}\vspace{1mm}%
}

% ── Card styles (dark mode, left accent stripe) ──
\tcbset{
  cyancard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cyancardtint,
    borderline west={4pt}{0pt}{stripecyan},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{stripecyan},
    coltitle=stripecyan, colbacktitle=bgtitle,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={stripecyan!40},
    valign=top,
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluecardtint,
    borderline west={4pt}{0pt}{stripeblue},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{stripeblue},
    coltitle=stripeblue, colbacktitle=bgtitle,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={stripeblue!40},
    valign=top,
  },
  greenhighlight/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=stripegreen!12!bgcard,
    borderline west={4pt}{0pt}{stripegreen},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{stripegreen},
    coltitle=stripegreen, colbacktitle=bgtitle,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=1.5pt, titlerule style={stripegreen!40},
    valign=top,
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0.5pt, colback=accent!10!bgcard,
    colframe=accent!30,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{30}{38}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accent!60!primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top,
  },
}

% ── Small stat callout ──
\newcommand{\statcallout}[3]{%
  \begin{minipage}[c]{0.31\linewidth}\centering
    \colorbox{bgstat}{\parbox{0.92\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{#1}{#2}\selectfont\bfseries\color{metriccyan}#3}\vspace{3pt}%
    }}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray}#3\vspace{2pt}}%
  \end{minipage}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════════
% TITLE BAR (span=2, rows 1-4)
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=32pt, right=32pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  borderline south={2pt}{0pt}{accent!50},
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{48}{58}\selectfont\bfseries Bot Mitigation at Scale}\\[10pt]
  {\fontsize{30}{38}\selectfont Protecting Scientific Publishing Platforms from Automated Threats}\\[14pt]
  {\fontsize{22}{30}\selectfont\color{textgray}
    \textit{IEEE Symposium on Security and Privacy (S\&P)} \hspace{16pt}
    \textbullet \hspace{16pt} www.science.org Case Study
  }
}

% ═══════════════════════════════════════════════════════════
% STATS BANNER — Key Metrics (span=2, rows 4-6)
% ═══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bgstat, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=5pt, bottom=5pt,
  valign=center,
  borderline south={2pt}{0pt}{secondary!30},
]{name=stats, column=1, span=2, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.23\linewidth}\centering
    {\fontsize{52}{62}\selectfont\bfseries\color{metriccyan}85\%}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray}Scraping Reduction}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    {\fontsize{52}{62}\selectfont\bfseries\color{stripegreen}99.97\%}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray}Platform Uptime}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    {\fontsize{52}{62}\selectfont\bfseries\color{metriccyan}\raisebox{2pt}{<\,2\,s}}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray}Verification Latency}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    {\fontsize{52}{62}\selectfont\bfseries\color{stripeblue}<\,0.3\%}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray}User Friction Reports}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════════
% COLUMN 1 (rows 6-20)
% ═══════════════════════════════════════════════════════════

% ── Threat Landscape (rows 6-9.5) ──
\posterbox[cyancard, title={The Bot Threat Landscape}
]{name=threat, column=1, between=row6 and row10}{
  \fontsize{24}{32}\selectfont
  \vspace{2pt}
  \centering
  \colorbox{secondary!20}{\parbox{0.92\linewidth}{\centering\vspace{5pt}
    {\fontsize{34}{42}\selectfont\bfseries\color{metriccyan}\raisebox{2pt}{$\mathbf{\approx}$\,47\%}}\\[2pt]
    {\fontsize{18}{24}\selectfont\color{textlight}of all internet traffic originates from bots}
  \vspace{4pt}}}
  \vspace{8pt}
  \begin{itemize}[itemsep=8pt]
    \item {\color{textlight}\textbf{30\% classified as malicious} — scraping, credential stuffing, DDoS}
    \item Academic publishers are \textbf{disproportionate targets} for full-text harvesting bots
    \item High-value IP (peer-reviewed articles, DOIs, datasets) attracts persistent automated threats
  \end{itemize}
}

% ── Verification Pipeline (rows 10-16) ──
\posterbox[bluecard, title={Challenge-Based Verification Pipeline}
]{name=pipeline, column=1, between=row10 and row16}{
  \fontsize{22}{30}\selectfont
  \vspace{2pt}
  \centering
  \begin{tikzpicture}[
    node distance=5mm,
    box/.style={
      rectangle, draw=stripeblue!60, fill=bgcard,
      text=textlight, rounded corners=2pt,
      minimum width=0.90\linewidth-10pt, minimum height=14mm,
      align=center, font=\fontsize{20}{26}\selectfont, line width=0.8pt,
    },
    arrow/.style={->, >=Stealth, line width=1.2pt, color=stripeblue!70},
    label/.style={font=\fontsize{16}{20}\selectfont\color{textgray}},
  ]
    \node[box, fill=stripeblue!15!bgcard, draw=stripeblue] (s1) {\textbf{① Request Interception}\\[2pt] {\small\color{textgray}HTTP request routed through CDN edge node \hspace{4pt} | \hspace{4pt} $<\,50$ ms}};
    \node[box, below=of s1] (s2) {\textbf{② Threat Scoring}\\[2pt] {\small\color{textgray}IP reputation $+$ TLS fingerprint $+$ behavioral signals \hspace{4pt} | \hspace{4pt} $\sim\,100$ ms}};
    \node[box, below=of s2] (s3) {\textbf{③ Challenge Issuance}\\[2pt] {\small\color{textgray}JS / CAPTCHA challenge served if risk exceeds threshold \hspace{4pt} | \hspace{4pt} $\sim\,500$ ms}};
    \node[box, below=of s3] (s4) {\textbf{④ Verification Check}\\[2pt] {\small\color{textgray}Client response validated; Ray ID assigned for tracing \hspace{4pt} | \hspace{4pt} $\sim\,200$ ms}};
    \node[box, below=of s4, fill=stripegreen!12!bgcard, draw=stripegreen!60] (s5) {\textbf{⑤ Access Grant}\\[2pt] {\small\color{textgray}Verified user forwarded to origin with session token \hspace{4pt} | \hspace{4pt} $<\,50$ ms}};
    \draw[arrow] (s1.south) -- (s2.north);
    \draw[arrow] (s2.south) -- (s3.north);
    \draw[arrow] (s3.south) -- (s4.north);
    \draw[arrow] (s4.south) -- (s5.north);
    \node[label, below=1mm of s5] {\textit{Total latency for legitimate user: < 2 seconds}};
  \end{tikzpicture}
  \vspace{2pt}
}

% ── Key Takeaways (rows 16-20) ──
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=1, between=row16 and bottom}{
  \fontsize{22}{30}\selectfont
  \vspace{2pt}
  \begin{enumerate}[itemsep=10pt]
    \item \textbf{Bot traffic dominates} — nearly half of all requests to academic publisher websites are automated.
    \item \textbf{Multi-stage CDN-edge verification} blocks the vast majority of malicious bots with minimal human impact.
    \item \textbf{Quantitative monitoring} via traceable identifiers (Ray IDs) enables continuous security--usability optimization.
  \end{enumerate}
  \vspace{4pt}
}

% ═══════════════════════════════════════════════════════════
% COLUMN 2 (rows 6-20)
% ═══════════════════════════════════════════════════════════

% ── Performance Outcomes (rows 6-11) ──
\posterbox[greenhighlight, title={Performance \& Security Outcomes}
]{name=outcomes, column=2, between=row6 and row11}{
  \fontsize{22}{30}\selectfont
  \vspace{3pt}
  \begin{itemize}[itemsep=8pt]
    \item \textbf{85\% reduction} in unauthorized bulk scraping within 6 months of deployment
    \item \textbf{99.97\% uptime} maintained even during 10$\times$ normal traffic bot surge events
    \item \textbf{$<\,0.3\%$} of legitimate users reported access friction from verification
    \item \textbf{$<\,150$ ms} average page-load overhead for verified sessions
  \end{itemize}
  \vspace{4pt}
  \centering
  \renewcommand{\arraystretch}{1.5}
  {\fontsize{18}{24}\selectfont
  \begin{tabular}{lcc}
    \hline
    \rowcolor{stripegreen!15}
    \textbf{Metric} & \textbf{Before} & \textbf{After} \\
    \hline
    Scraping attempts/day & 1.2M & {\color{stripegreen}\textbf{180K}} \\
    Origin server CPU & 78\% & {\color{stripegreen}\textbf{42\%}} \\
    User complaints/mo & 1,200 & {\color{stripegreen}\textbf{340}} \\
    Uptime (bot surges) & 98.5\% & {\color{stripegreen}\textbf{99.97\%}} \\
    \hline
  \end{tabular}}
  \vspace{2pt}
}

% ── Trade-offs (rows 11-16) ──
\posterbox[cyancard, title={Usability vs.\ Security Trade-offs}
]{name=tradeoffs, column=2, between=row11 and row16}{
  \fontsize{22}{30}\selectfont
  \vspace{3pt}
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Accessibility:} Challenge pages must comply with WCAG 2.1 to avoid excluding users with disabilities.
    \item \textbf{Institutional access:} University IP allowlisting reduces unnecessary challenges for campus researchers.
    \item \textbf{Transparency:} Clear status messaging helps users understand brief verification delays.
    \item \textbf{Privacy:} Security services balance threat detection with user data protection and disclosure.
  \end{itemize}
  \vspace{2pt}
  \centering
  \colorbox{stripecyan!18}{\parbox{0.90\linewidth}{\centering\vspace{5pt}
    {\fontsize{20}{26}\selectfont\color{textlight}
    The verification layer introduces friction — \textbf{mitigating this} while maintaining security efficacy is the central design challenge.}
  \vspace{4pt}}}
  \vspace{2pt}
}

% ── References & About (rows 16-20) ──
\posterbox[bluecard, title={Collaboration \& Future Directions}
]{name=references, column=2, between=row16 and bottom}{
  \fontsize{20}{28}\selectfont
  \vspace{2pt}
  \begin{itemize}[itemsep=6pt]
    \item CDN--publisher collaboration is \textbf{critical} for sustaining open, secure access to scientific knowledge.
    \item Continuous refinement of risk-scoring models using Ray ID telemetry.
    \item Future: ML-driven adaptive challenge difficulty based on real-time threat intelligence.
  \end{itemize}
  \vspace{4pt}
  \centering
  {\fontsize{18}{24}\selectfont\color{textmuted}
  \faShieldAlt \hspace{4pt} Case Study: www.science.org (AAAS) \hspace{4pt} \faShieldAlt \\[3pt]
  CDN Security: Cloudflare Bot Management}
}

\end{tcbposter}
\end{document}

